ENV = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
ENV.update(GIT_AUTHOR_NAME="t", GIT_AUTHOR_EMAIL="t@example.invalid", GIT_COMMITTER_NAME="t", GIT_COMMITTER_EMAIL="t@example.invalid")
def git(cwd, *a):
    return subprocess.run(["git", *a], cwd=cwd, env=ENV, check=True, capture_output=True, text=True).stdout
def refs(r):
    return dict(l.split(" ") for l in git(r, "for-each-ref", "--format=%(refname:lstrip=2) %(objectname:short)", "refs/heads").splitlines())
def wt_branches(r):
    out = []
    items = git(r, "worktree", "list", "--porcelain").strip().split("\n\n")
    for it in items[1:]:
        for l in it.splitlines():
            if l.startswith("branch refs/heads/"):
                out.append(l[len("branch refs/heads/"):])
    return out
def snapshot(r):
    return refs(r), wt_branches(r)
def compare(r, before):
    b_refs, b_wt = before
    now = refs(r); excl = set(b_wt) | set(wt_branches(r))
    a = {k: v for k, v in b_refs.items() if k not in excl}
    c = {k: v for k, v in now.items() if k not in excl}
    gone = sorted(set(a) - set(c)); added = sorted(set(c) - set(a))
    moved = sorted(k for k in set(a) & set(c) if a[k] != c[k])
    return "停止しない" if not (gone or added or moved) else f"RR1 消えた={gone} 増えた={added} 変わった={moved}"
def fresh():
    d = tempfile.mkdtemp(dir=sys.argv[1]); r = os.path.join(d, "repo"); os.mkdir(r)
    git(r, "init", "-q", "-b", "main"); git(r, "commit", "-q", "--allow-empty", "-m", "c")
    return r, d
def case(title, setup, during):
    r, d = fresh(); setup(r, d); before = snapshot(r); during(r, d)
    print(f"{title}: {compare(r, before)}")
wt = lambda d, n: os.path.join(d, n)
def add(r, d, n, b): git(r, "worktree", "add", "-q", "-b", b, wt(d, n))
def detach(d, n): git(wt(d, n), "checkout", "-q", "--detach")
def s1(r, d): git(r, "branch", "leftover")
case("A 依頼の前からあり、チェックアウトされていないブランチを待機中に消す", s1, lambda r, d: git(r, "branch", "-D", "leftover"))
def d2(r, d): add(r, d, "w", "new-session"); detach(d, "w")
case("B 待機中に起動したセッションの HEAD が detached になり、ブランチが残る", lambda r, d: None, d2)
def d3(r, d): add(r, d, "w", "new-session"); detach(d, "w"); git(r, "branch", "-D", "new-session")
case("C B の後、比べる前にブランチも消す", lambda r, d: None, d3)
def d4(r, d): add(r, d, "w", "new-session")
case("D 待機中に起動したセッションがブランチをチェックアウトしたまま", lambda r, d: None, d4)
def s5(r, d): add(r, d, "w", "other-loop")
def d5(r, d): detach(d, "w")
case("E 依頼の前からチェックアウトされているブランチの HEAD が待機中に detached になる", s5, d5)
def d6(r, d): detach(d, "w"); git(r, "branch", "-D", "other-loop")
case("F E の後、ブランチも消す", s5, d6)
def s7(r, d): add(r, d, "w", "other-loop"); detach(d, "w")
def d7(r, d): git(r, "branch", "-D", "other-loop")
case("G 依頼の前に detached になっていたセッションのブランチを待機中に消す", s7, d7)
